import {find,isLocked,selectionRoots,locate} from '../document/model.js';import {escape} from '../renderer/svg.js';import {shapeTools,shapePalette,chooseShape} from './shapes-menu.js';import {editorAction,editorInput,lineNoiseControls} from './editor.js';import {showHelp} from './help.js';
const combineIcon=action=>{const a='<rect x="3" y="3" width="13" height="13"/>',b='<rect x="10" y="10" width="13" height="13"/>';return `<svg viewBox="0 0 26 26" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8">${action==='combine-union'?'<path fill="currentColor" d="M3 3H16V10H23V23H10V16H3Z"/>':action==='combine-intersect'?a+b+'<rect x="10" y="10" width="6" height="6" fill="currentColor"/>':action==='combine-subtract'?'<path fill="currentColor" d="M3 3H16V10H10V16H3Z"/>'+b:action==='combine-exclude'?'<path fill="currentColor" d="M3 3H16V10H10V16H3ZM16 10H23V23H10V16H16Z"/>':a+b}</svg>`;};
const button=(action,label,disabled=false)=>`<button data-edit="${action}" ${action.startsWith('combine-')?`class="combine-icon" title="${label}" aria-label="${label}"`:""} ${disabled?'disabled':''}>${action.startsWith('combine-')?combineIcon(action):''}<span>${label}</span></button>`;
export function contextControls(a){const n=find(a.doc,a.selected[0]),disabled=!n||isLocked(a.doc,n.id);let mode=a.tool==='mesh'?'Mesh shading':a.tool==='direct'?'Edit points':shapeTools.includes(a.tool)?'Drawing: '+({rect:'Rectangle',ellipse:'Ellipse',triangle:'Triangle',polygon:'Polygon',star:'Star',line:'Line'}[a.tool]):a.tool==='select'?'Select objects':a.tool==='path'?'Draw a path':a.tool==='pencil'?'Draw with Pencil':a.tool==='text'?'Add text':'Pan canvas',body='';
 if(a.selected.length>1){mode=a.selected.length+' selected';const roots=selectionRoots(a.doc,a.selected),same=roots.length>1&&roots.every(n=>!isLocked(a.doc,n.id)&&locate(a.doc,n.id).list===locate(a.doc,roots[0].id).list),canCombine=same&&roots.every(n=>['rectangle','ellipse'].includes(n.type)||['path','freehand'].includes(n.type)&&(n.closed||n.rawPath||n.nodes.some(p=>p.close))),canJoin=same&&roots.length===2&&roots.every(n=>['path','freehand'].includes(n.type)&&!n.rawPath&&n.nodes.length>=2&&!n.closed&&!n.nodes.some(p=>p.close));body=`<span class="context-label">Combine shapes</span>${button('combine-union','Unite',!canCombine)}${button('combine-subtract','Subtract front',!canCombine)}${button('combine-intersect','Keep overlap',!canCombine)}${button('combine-exclude','Exclude overlap',!canCombine)}${button('combine-compound','Compound path',!canCombine)}${button('join','Join paths',!canJoin)}<span class="context-note">${canCombine?'Combining uses the current frame. Undo restores the originals.':'Choose closed shapes in the same group to combine.'}</span>`;}
 else if(n&&a.tool==='mesh'&&n.mesh){const mesh=currentMesh(n,a.time),index=Math.min(a.activeMesh||0,mesh.points.length-1),p=mesh.points[index];mode=a.meshPlacement?`${a.meshPlacement.first?'Tap opposite side':'Tap first side'} · ${n.name}`:a.meshInsert?`Tap inside shading to add a point · ${n.name}`:`Mesh · ${n.name} · point ${index+1}`;body=`${button('mesh-bounds','Set mesh bounds',disabled)+button('mesh-insert',a.meshInsert?'Tap to add point':'Add mesh point',disabled||(mesh.rows>=17&&mesh.cols>=17))}${button('mesh-colour','Point colour',disabled)+button('mesh-key',n.tracks.mesh?.length?'● Add mesh key':'● Animate mesh',disabled)}${button('mesh-fit','Fit to shape',disabled)+button('mesh-split','Subdivide cell',disabled||mesh.rows>=17||mesh.cols>=17)}<button data-edit="mesh-tap" aria-pressed="${!!a.meshSplit}" ${mesh.rows>=17||mesh.cols>=17?'disabled':''} class="${a.meshSplit?'active':''}" ${disabled?'disabled':''}>Tap to subdivide</button>${button('mesh-row','More rows',disabled||mesh.rows>=17)}${button('mesh-col','More columns',disabled||mesh.cols>=17)}${a.meshPlacement?button('mesh-placement-cancel','Cancel placement'):''}<span class="context-note">${a.meshPlacement?'Tap one side/corner, then the opposite side/corner. ':''}${mesh.rows} × ${mesh.cols} grid · hold a point for colour · maximum 17 × 17</span>`;}
 else if(n&&a.nodeEdit&&['path','freehand'].includes(n.type)&&!n.rawPath){mode=`Edit points · ${n.name}${Number.isInteger(a.activeNode)?' · point '+(a.activeNode+1):''}`;const pointDisabled=disabled||!Number.isInteger(a.activeNode);body=button('previous-point','‹ Point',disabled)+button('next-point','Point ›',disabled)+button('split','Add midpoint',pointDisabled)+button('curve','Convert to curve',pointDisabled)+button('smooth','Smooth point',pointDisabled)+button('corner','Corner point',pointDisabled)+button('delete-point','Delete point',pointDisabled)+button('toggle-close',n.closed||n.nodes.some(p=>p.close)?'Open path':'Close path',disabled)+button('reverse','Reverse path',disabled)+button('shape-key',n.tracks.nodes?.length?'● Add shape key':'● Animate points',disabled)+`<span class="context-note">${n.tracks.nodes?.length?'Point edits create keys at '+a.time.toFixed(2)+'s':'Enable Animate points, then change points at a later time.'}</span>`;}
 else if(n?.reference){mode='Reference · '+n.name;body='<span class="context-note">Baked frames for tracing · draw on a layer above · Layer adjusts opacity and export visibility.</span>';}else if(n){if(n.type==='text')mode='Edit text';mode+=' · '+n.name;body=button('direct',n.type==='text'?'Edit text':n.type==='group'?'Direct select':'Edit points',disabled)+(n.type==='group'?button('contents','Select contents',disabled):'')+`<button data-add-key ${disabled?'disabled':''}>● Add keyframe</button>`;}
 else body='<span class="context-note">Choose Shapes → draw → Add keyframe. Drag empty canvas to select several.</span>';
 if(n&&!(a.tool==='mesh'&&n.mesh)&&['rectangle','ellipse','path','freehand'].includes(n.type)&&!n.rubberhoseRig?.enabled){const status=meshShapeStatus(evaluated(n,a.time));body+=status.supported?button('mesh',n.mesh?'Edit mesh':'Add colour mesh',disabled):button('mesh-close','Close drawing & add mesh',disabled||!status.closable)+`<span class="context-note">${escape(status.reason)}</span>`;}
 if(a.selected.length===1&&n&&n.type!=='group'&&n.type!=='text'&&n.type!=='image'&&a.tool!=='mesh'){if(n.fill!=='none')body+=`<label class="context-color">Fill<input type="color" aria-label="Shape fill colour" data-prop="fill" value="${evaluated(n,a.time).fill==='none'?a.drawColor:evaluated(n,a.time).fill}" ${disabled?'disabled':''}></label>`;if(n.fill==='none'||n.strokeWidth>0)body+=`<div class="line-dock"><label>Width<input data-prop="strokeWidth" aria-label="Line width" type="number" min="0" step="1" value="${evaluated(n,a.time).strokeWidth}" style="width:60px"></label><label>Style<select data-prop="lineStyle" aria-label="Line style">${['solid','dashed','dotted'].map(x=>' <option '+(x===(n.lineStyle||'solid')?'selected':'')+'>'+x+'</option>').join('')}</select></label><label>Profile<select data-prop="strokeProfile" aria-label="Line width profile">${[['uniform','Uniform'],['taper-both','Taper ends'],['taper-start','Thin to thick'],['taper-end','Thick to thin'],['brush','Brush']].map(([v,label])=>'<option value="'+v+'" '+(v===(n.strokeProfile||'uniform')?'selected':'')+'>'+label+'</option>').join('')}</select></label></div>`;}
 if(n&&a.nodeEdit&&['path','freehand'].includes(n.type)&&!n.rawPath){const selected=Number.isInteger(a.activeNode)&&evaluated(n,a.time).nodes[a.activeNode],pointDisabled=disabled||!selected;body+=`<label class="point-bevel">Bevel radius (px)<input type="number" min="0" max="2048" step="1" data-node-prop="bevelRadius" aria-label="Selected point bevel radius" value="${selected?.bevelRadius||0}" ${pointDisabled?'disabled':''}><select data-node-prop="bevelStyle" aria-label="Selected point bevel style" ${pointDisabled?'disabled':''}><option value="round" ${selected?.bevelStyle!=='bevel'?'selected':''}>Round</option><option value="bevel" ${selected?.bevelStyle==='bevel'?'selected':''}>Flat bevel</option></select></label>`;}if(n&&!['group','text','image'].includes(n.type))body+=button('texture',n.texture?'Edit texture':'Image texture',disabled)+(n.texture?button('texture-remove','Remove texture',disabled):'');if(n)body+=`<button data-motion-blur aria-haspopup="dialog" ${disabled?'disabled':''}>Motion blur…</button>`;return {mode,body,n};
}
export function renderContext(a){
 initWorkspace(a);const el=document.querySelector('#context-bar'),{mode,body,n}=contextControls(a),active=document.activeElement;if(el.contains(active)&&active?.matches('input,select'))return;
 const properties=`<button class="context-properties" data-properties aria-expanded="${!!a.propertiesOpen}" aria-controls="properties-panel">Properties</button>`;
 const colour=n&&n.type!=='image'?`<div class="object-colour-controls"><button data-object-colour="fill" ${isLocked(a.doc,n.id)?'disabled':''}><span class="colour-chip" style="--swatch:${escape(evaluated(n,a.time).fill==='none'?'transparent':evaluated(n,a.time).fill)}"></span>Fill</button><button data-object-colour="stroke" ${isLocked(a.doc,n.id)?'disabled':''}><span class="colour-chip" style="--swatch:${escape(evaluated(n,a.time).stroke==='none'?'transparent':evaluated(n,a.time).stroke)}"></span>Stroke</button><button data-object-pivot aria-pressed="${!!a.pivotEdit}" ${isLocked(a.doc,n.id)?'disabled':''}>${a.pivotEdit?'Done pivot':'Pivot'}</button>${a.pivotEdit?'<button data-pivot-centre>Centre pivot</button>':''}</div>`:'';
 const heading=`<strong title="${escape(mode)}">${escape(mode)}</strong>`;
 el.innerHTML=a.workspaceGuided?`<div class="context-compact guided-context">${heading}${colour}<button data-object-options aria-haspopup="dialog" ${!n?'disabled':''}>Object options</button>${properties}</div>`:`<div class="context-compact detailed-context">${heading}${colour}<div class="context-actions">${a.shapesOpen?shapePalette(a):''}${n?body:''}<button data-layer-menu ${!n?'disabled':''}>${layerOptionsLabel(n)}</button><button data-layer-graph ${!n?'disabled':''}>Graph</button>${properties}</div></div>`;
}
function bindOptions(a,el,popup=false){
 el.addEventListener('click',e=>{const timing=e.target.closest('[data-layer-timing]');if(timing&&!timing.disabled){if(popup)el.closest('dialog')?.close();return a.safe(()=>timing.dataset.layerTiming==='move'?showLayerMove(a,nId(a)):showLayerStretch(a,nId(a)));}const arrange=e.target.closest('[data-layer-order]');if(arrange&&!arrange.disabled){if(popup)el.closest('dialog')?.close();return a.safe(()=>performLayerOrder(a,arrange.dataset.layerOrder));}const shape=e.target.closest('[data-shape]')?.dataset.shape;if(shape)return chooseShape(a,shape);const action=e.target.closest('[data-edit]')?.dataset.edit;if(action){if(popup)el.closest('dialog')?.close();return a.safe(()=>editorAction(a,action));}if(e.target.closest('[data-add-key]')){if(popup)el.closest('dialog')?.close();return document.querySelector('#add-key').click();}if(e.target.closest('[data-motion-blur]')){if(popup)el.closest('dialog')?.close();return a.showMotionBlur?.(a.selected[0]);}if(e.target.closest('[data-layer-menu]')){if(popup)el.closest('dialog')?.close();return showLayerMenu(a);}if(e.target.closest('[data-layer-graph]')){if(popup)el.closest('dialog')?.close();return showGraph(a);}if(e.target.closest('[data-context-help]')){if(popup)el.closest('dialog')?.close();return showHelp(a);}if(e.target.closest('[data-properties]')){if(popup){el.closest('dialog')?.close();return setInspector(a,true);}return toggleInspector(a);}if(e.target.closest('[data-object-options]'))showObjectOptions(a);});
 el.addEventListener('input',e=>a.properties.input(e));el.addEventListener('change',e=>{if(a.properties.pending)a.properties.flush();else a.properties.change(e);if(!e.target.matches('input[type=color]'))a.render();});
}
export function layerOptionsLabel(n){return n?.reference?'Reference options':n?.type==='group'?'Group options':'Drop shadow';}
export function contextControlGroup(el,tool='select',type='path'){
 const d=el.dataset||{},edit=d.edit;
 if(d.addKey!==undefined||['shape-key','mesh-key'].includes(edit))return 'Animation';
 if(d.nodeProp!==undefined||el.querySelector?.('[data-node-prop]'))return 'Geometry';
 if(d.motionBlur!==undefined||d.layerMenu!==undefined||d.prop!==undefined||el.querySelector?.('[data-prop]')||edit==='mesh'||edit?.startsWith('mesh-')||edit==='highlight'||edit?.startsWith('texture'))return 'Appearance';
 if(edit==='contents'||edit==='direct'&&type==='group')return 'Selection';
 if(edit==='direct')return 'Geometry';
 return tool==='mesh'?'Appearance':'Geometry';
}
export const objectOptionTabs=[['artwork','Shape & style'],['animate','Animate'],['arrange','Arrange']];
export function objectOptionMarkup(groups){
 const section=(name,items)=>items?.some(Boolean)?'<section class="object-option-group" aria-label="'+name+'"><h3>'+name+'</h3><div class="object-option-controls">'+items.join('')+'</div></section>':'';
 const panels={artwork:section('Points & geometry',groups.Geometry)+section('Colour & effects',groups.Appearance),animate:section('Keyframes & motion',groups.Animation),arrange:section('Layer stacking',groups.Arrange)+section('Selection & grouping',groups.Selection)};
 return '<div class="object-option-tabs" role="tablist" aria-label="Object editing sections">'+objectOptionTabs.map(([id,label],i)=>`<button id="object-option-tab-${id}" role="tab" data-object-option-tab="${id}" aria-selected="${i===0}" aria-controls="object-option-panel-${id}" tabindex="${i===0?0:-1}">${label}</button>`).join('')+'</div>'+objectOptionTabs.map(([id],i)=>`<div id="object-option-panel-${id}" class="object-option-panel" role="tabpanel" aria-labelledby="object-option-tab-${id}" ${i===0?'':'hidden'}>${panels[id]||'<p class="subtle">No controls for this selection.</p>'}</div>`).join('')+'<footer class="object-options-footer"><button data-properties>Open all Properties</button></footer>';
}
export function contextOptionSections(a,body,n){
 const box=document.createElement('div');box.innerHTML=body;const groups={Geometry:[],Appearance:[],Animation:[],Selection:[],Arrange:[layerOrderControls(a)]};
 for(const el of box.children){const group=contextControlGroup(el,a.tool,n.type);if(groups[group])groups[group].push(el.outerHTML);}
 const noise=lineNoiseControls(evaluated(n,a.time));if(noise)groups.Appearance.push(noise);
 groups.Appearance.push('<button data-layer-menu>'+layerOptionsLabel(n)+'</button>');
 groups.Animation.push('<button data-layer-graph>Animation graph</button>');if(a.selected.length===1)groups.Animation.push(`<button data-layer-timing="move" ${canMoveLayerSequence(a.doc,n.id)?'':'disabled'}>Move sequence…</button><button data-layer-timing="stretch" ${canMoveLayerSequence(a.doc,n.id)?'':'disabled'}>Stretch animation…</button>`);
 groups.Selection.push(controlCopies(['multi','group','ungroup','duplicate','delete']));
 return objectOptionMarkup(groups);
}
export function bindObjectOptionTabs(d){
 const select=(id,focus=false)=>{d.dataset.popupCategory=id==='animate'?'animation':id==='arrange'?'arrange':'artwork';for(const tab of d.querySelectorAll('[data-object-option-tab]')){const chosen=tab.dataset.objectOptionTab===id;tab.setAttribute('aria-selected',chosen);tab.tabIndex=chosen?0:-1;if(chosen&&focus)tab.focus();}for(const panel of d.querySelectorAll('.object-option-panel'))panel.hidden=panel.id!=='object-option-panel-'+id;};
 d.addEventListener('click',e=>{const tab=e.target.closest('[data-object-option-tab]');if(tab)select(tab.dataset.objectOptionTab);});
 d.addEventListener('keydown',e=>{const tab=e.target.closest('[data-object-option-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ids=objectOptionTabs.map(([id])=>id),index=ids.indexOf(tab.dataset.objectOptionTab),next=e.key==='Home'?0:e.key==='End'?ids.length-1:(index+(e.key==='ArrowLeft'?-1:1)+ids.length)%ids.length;select(ids[next],true);});
}
export function showObjectOptions(a){const {mode,body,n}=contextControls(a);if(!n)return;const d=a.dialog('Object options','<p class="object-options-title">'+escape(mode)+'</p><div class="object-options-groups">'+contextOptionSections(a,body,n)+'</div>');d.classList.add('object-options-dialog');bindObjectOptionTabs(d);bindOptions(a,d,true);bindControlCopies(a,d);if(isLocked(a.doc,n.id))for(const control of d.querySelectorAll('input,select,[data-edit],[data-motion-blur]'))control.disabled=true;return d;}

export function bindContext(a){bindOptions(a,document.querySelector('#context-bar'));}

function nId(a){return a.selected[0];}
